// counter.js -- only the factory is exported
const state = new WeakMap();                  // invisible to importers

export function createCounter(start = 0) {
  const counter = {
    increment: () => state.set(counter, state.get(counter) + 1),
    value: () => state.get(counter),
  };
  state.set(counter, start);
  return counter;
}
